#include <iostream>

inline void calculateRectangle(int width, int height, int &area, int &perimeter) {
    area = width * height;
    perimeter = 2 * (width + height);
}

int main() {
    int w = 5, h = 8;
    int area = 0, perimeter = 0;

    calculateRectangle(w, h, area, perimeter);

    std::cout << "Width: " << w << ", Height: " << h << "\n";
    std::cout << "Area: " << area << "\n";
    std::cout << "Perimeter: " << perimeter << "\n";

    return 0;
}
